# -*- coding: utf-8 -*-

from taf.internal.bmc.interfaces.redfish.rm17.system import SystemRm17
from taf.internal.bmc.interfaces.bmc import BmcResponse


class SystemOe19(SystemRm17):
    SYSTEM_RESET_PATH = "/redfish/v1/Systems/Self/Actions/ComputerSystem.Reset"

    def power_off_immediate(self):
        """
        Perform immediate poweroff reset on system named "Self".

        :return: BmcResponse object, with status response and data.
        """
        return self.__computer_system_reset(reset_type="ForceOff")

    def power_on(self):
        """
        Power on system named "Self".

        :return: BmcResponse object, with status response and data.
        """
        return self.__computer_system_reset(reset_type="On")

    def __computer_system_reset(self, reset_type):
        protocol_response = self.protocol.post(
            path=self.SYSTEM_RESET_PATH,
            body={"ResetType": reset_type})
        return BmcResponse(status=protocol_response.status, data=protocol_response.dict)
